'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);

const N = input[0];
const K = input[1];
const dolls = input.slice(2).sort((a, b) => a - b);

let prev = new Float64Array(N + 1); // Zero trios cost 0 for any prefix.

for (let k = 1; k <= K; k++) {
  const curr = new Float64Array(N + 1);
  curr.fill(Infinity);

  for (let i = 1; i <= N; i++) {
    curr[i] = curr[i - 1];

    if (i >= 3) {
      const cost = dolls[i - 2] - dolls[i - 3];
      curr[i] = Math.min(curr[i], prev[i - 3] + cost * cost);
    }
  }

  prev = curr;
}

console.log(prev[N].toString());
